using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public sealed class TicketInput
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public sealed class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

public sealed class TicketRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

public sealed class TicketResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> Confidence { get; set; } = new();
}

public sealed class MetricsResponse
{
    public double MicroAccuracy { get; set; }
    public double MacroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public double LogLossReduction { get; set; }
    public List<PerClassMetric> PerClassMetrics { get; set; } = [];
}

public sealed class PerClassMetric
{
    public string ClassName { get; set; } = string.Empty;
    public double Precision { get; set; }
    public double Recall { get; set; }
    public double F1Score { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class ModelTrainingService
{
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<ModelTrainingService> _logger;

    public MetricsResponse? LastMetrics { get; private set; }

    public ModelTrainingService(ILogger<ModelTrainingService> logger)
    {
        _logger = logger;
        _dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        _modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
    }

    public string ModelPath => _modelPath;

    public void TrainAndEvaluate()
    {
        var mlContext = new MLContext(seed: 42);

        var data = mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = mlContext.Transforms.Text
                .FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject))
            .Append(mlContext.Transforms.Text
                .FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
            .Append(mlContext.Transforms.Concatenate("Features",
                "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
            .Append(mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketInput.Category)))
            .Append(mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training model from {DataPath}...", _dataPath);
        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.MulticlassClassification.Evaluate(predictions);

        _logger.LogInformation(
            "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);

        LastMetrics = BuildMetricsResponse(metrics);

        mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {ModelPath}", _modelPath);
    }

    private static MetricsResponse BuildMetricsResponse(
        Microsoft.ML.Data.MulticlassClassificationMetrics m)
    {
        var response = new MetricsResponse
        {
            MicroAccuracy = m.MicroAccuracy,
            MacroAccuracy = m.MacroAccuracy,
            LogLoss = m.LogLoss,
            LogLossReduction = m.LogLossReduction,
        };

        for (var i = 0; i < m.PerClassLogLoss.Count; i++)
        {
            response.PerClassMetrics.Add(new PerClassMetric
            {
                ClassName = $"Class{i}",
                Precision = i < m.ConfusionMatrix.PerClassPrecision.Count
                    ? m.ConfusionMatrix.PerClassPrecision[i] : 0,
                Recall = i < m.ConfusionMatrix.PerClassRecall.Count
                    ? m.ConfusionMatrix.PerClassRecall[i] : 0,
                F1Score = i < m.ConfusionMatrix.PerClassPrecision.Count
                          && i < m.ConfusionMatrix.PerClassRecall.Count
                    ? 2 * m.ConfusionMatrix.PerClassPrecision[i] * m.ConfusionMatrix.PerClassRecall[i]
                      / (m.ConfusionMatrix.PerClassPrecision[i] + m.ConfusionMatrix.PerClassRecall[i] + 1e-9)
                    : 0,
            });
        }

        return response;
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public sealed class TicketController : ControllerBase
{
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _pool;
    private readonly ModelTrainingService _training;

    public TicketController(
        PredictionEnginePool<TicketInput, TicketPrediction> pool,
        ModelTrainingService training)
    {
        _pool = pool;
        _training = training;
    }

    [HttpPost("predict")]
    public ActionResult<TicketResponse> Predict([FromBody] TicketRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority,
        };

        var prediction = _pool.Predict(input);

        var labels = new[] { "Billing", "General", "Technical" };
        var confidence = new Dictionary<string, float>();
        for (var i = 0; i < labels.Length && i < prediction.Score.Length; i++)
            confidence[labels[i]] = prediction.Score[i];

        return Ok(new TicketResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence,
        });
    }

    [HttpGet("metrics")]
    public ActionResult<MetricsResponse> GetMetrics()
    {
        if (_training.LastMetrics is null)
            return NotFound("Model has not been trained yet.");

        return Ok(_training.LastMetrics);
    }

    [HttpPost("retrain")]
    public ActionResult Retrain()
    {
        _training.TrainAndEvaluate();
        return Ok(_training.LastMetrics);
    }
}

